// Run config — the one place to change the collection window and output folders.
// Every downstream node reads these values via $('Run config').
const LOOKBACK_DAYS = 45;          // AI-industry sources (same as A3)
const BRAND_LOOKBACK_DAYS = 90;    // Weave + competitor sources: brand news is sparser

let dataDir, outDir;
try {
  dataDir = $env.GROUNDLINE_DATA_DIR;
  outDir = $env.GROUNDLINE_OUTPUT_DIR;
} catch (e) {
  throw new Error('n8n is blocking environment variables. Start n8n with scripts/start-n8n.ps1 (it sets N8N_BLOCK_ENV_ACCESS_IN_NODE=false).');
}
if (!dataDir || !outDir) {
  throw new Error('GROUNDLINE_DATA_DIR / GROUNDLINE_OUTPUT_DIR are not set. Start n8n with scripts/start-n8n.ps1 so the workflow knows where to save files.');
}

const now = new Date();
const since = new Date(now.getTime() - Math.max(LOOKBACK_DAYS, BRAND_LOOKBACK_DAYS) * 86400000);
const slash = (p) => p.split('\\').join('/').replace(/\/$/, '');

return [{
  json: {
    run_id: now.toISOString().replace(/[-:]/g, '').slice(0, 15) + 'Z',
    run_date: now.toISOString().slice(0, 10),
    collected_at: now.toISOString(),
    lookback_days: LOOKBACK_DAYS,
    brand_lookback_days: BRAND_LOOKBACK_DAYS,
    since_iso: since.toISOString(),
    since_unix: Math.floor(new Date(now.getTime() - LOOKBACK_DAYS * 86400000).getTime() / 1000),
    data_dir: slash(dataDir),
    out_dir: slash(outDir),
  },
}];

// Source 1 — News RSS feeds. No key, no rate limit.
// A3: three AI desks + Google News searches for agents, grounding and Weave.
// v2: adds Weave's direct competitors and practice-owner discussion on Reddit,
// so the agent can compare Weave against the market instead of seeing it alone.
// Brand feeds use a longer window (90 days) because brand news is sparser.
const cfg = $('Run config').first().json;
const gnews = (q, days) =>
  'https://news.google.com/rss/search?q=' + encodeURIComponent(`${q} when:${days}d`) +
  '&hl=en-US&gl=US&ceid=US:en';
const A = cfg.lookback_days;
const B = cfg.brand_lookback_days;

const feeds = [
  // --- AI market context (unchanged from A3)
  { feed_id: 'techcrunch_ai',          source_name: 'TechCrunch',            focus_hint: 'AI',    window_days: A, url: 'https://techcrunch.com/category/artificial-intelligence/feed/' },
  { feed_id: 'mit_tech_review_ai',     source_name: 'MIT Technology Review', focus_hint: 'AI',    window_days: A, url: 'https://www.technologyreview.com/topic/artificial-intelligence/feed' },
  { feed_id: 'the_verge_ai',           source_name: 'The Verge',             focus_hint: 'AI',    window_days: A, url: 'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml' },
  { feed_id: 'gnews_ai_agents',        source_name: 'Google News',           focus_hint: 'AI',    window_days: A, url: gnews('"AI agents" (analytics OR enterprise OR data)', A) },
  { feed_id: 'gnews_ai_grounding',     source_name: 'Google News',           focus_hint: 'AI',    window_days: A, url: gnews('"AI hallucinations" OR "retrieval-augmented generation" OR "AI grounding"', A) },
  { feed_id: 'gnews_ai_customer_comms', source_name: 'Google News',          focus_hint: 'AI',    window_days: B, url: gnews('"AI receptionist" OR "AI front desk" OR "patient communication" AI', B) },
  // --- The brand
  { feed_id: 'gnews_weave',            source_name: 'Google News',           focus_hint: 'Weave', window_days: B, url: gnews('"Weave Communications" OR "getweave" OR "NYSE: WEAV"', B) },
  // --- Competitors (v2). Deliberately broad: "Podium" also matches F1 race results,
  // and telling those apart is a job for the AI relevance check, not a keyword list.
  { feed_id: 'gnews_podium',           source_name: 'Google News',           focus_hint: 'Competitor', entity_hint: 'Podium',        window_days: B, url: gnews('"Podium" (software OR ServiceTitan OR "text marketing" OR reviews OR "local business" OR AI)', B) },
  { feed_id: 'gnews_birdeye',          source_name: 'Google News',           focus_hint: 'Competitor', entity_hint: 'Birdeye',       window_days: B, url: gnews('"Birdeye"', B) },
  { feed_id: 'gnews_nexhealth',        source_name: 'Google News',           focus_hint: 'Competitor', entity_hint: 'NexHealth',     window_days: B, url: gnews('"NexHealth" OR "Solutionreach" OR "RevenueWell" OR "Lighthouse 360"', B) },
  // --- Practice owners talking (v2, optional: Reddit often throttles anonymous readers)
  { feed_id: 'reddit_practice_owners', source_name: 'Reddit',                focus_hint: 'Competitor', window_days: 365,
    url: 'https://www.reddit.com/r/Dentistry+Optometry+veterinaryprofession+smallbusiness/search.rss?q=' +
         encodeURIComponent('weave OR podium OR nexhealth OR birdeye OR solutionreach') + '&restrict_sr=1&sort=new&t=year' },
];

return feeds.map((f) => ({ json: f }));

// Normalize RSS → common record shape.
// Also emits one status row per feed (ok / empty / unavailable) so a dead
// feed shows up in the quality report instead of silently disappearing.
const feeds = $('RSS feed list').all().map((i) => i.json);

const out = [];
const stats = Object.fromEntries(feeds.map((f) => [f.feed_id, { fetched: 0, error: null }]));

for (const item of $input.all()) {
  const { _feed, ...j } = item.json || {};
  const feed = _feed || feeds[0];
  if (j.error) { stats[feed.feed_id].error = String(j.error.message || j.error); continue; }
  if (!j.title && !j.link) continue; // empty placeholder from alwaysOutputData
  stats[feed.feed_id].fetched++;
  out.push({
    json: {
      _type: 'record',
      source_type: 'news_rss',
      feed_id: feed.feed_id,
      source_name: feed.source_name,
      focus_hint: feed.focus_hint,
      entity_hint: feed.entity_hint || '',
      window_days: feed.window_days,
      title: j.title,
      summary: j.contentSnippet || j.content || j.summary || '',
      author: j.creator || j.author || '',
      url: j.link,
      published_raw: j.isoDate || j.pubDate || '',
      engagement_points: null,
      engagement_comments: null,
      raw: j,
    },
  });
}

for (const f of feeds) {
  const s = stats[f.feed_id];
  out.push({ json: {
    _type: 'status', source_type: 'news_rss', feed_id: f.feed_id, fetched: s.fetched,
    status: s.error ? 'unavailable' : s.fetched ? 'ok' : 'empty',
    message: s.error ? `Source unavailable: ${s.error}` : s.fetched ? '' : 'Feed returned no items',
  }});
}
return out;

// Tag each response with the feed it came from.
// The loop fetches one feed per run, so run N belongs to feed N in the list.
// Tagging here means every record — and every error — is credited to the right feed.
const feeds = $('RSS feed list').all();
const feed = feeds[$runIndex]?.json;
if (!feed) throw new Error(`No feed at position ${$runIndex} in RSS feed list`);
return $input.all().map((i) => ({ json: { ...i.json, _feed: feed } }));

// Normalize arXiv (Atom XML) → common record shape.
// Research signal: what is being published on grounding, hallucination and agents.
// The HTTP node returns the raw XML as text; each <entry> is one paper.
const out = [];
let fetched = 0, error = null;

const tag = (xml, name) => {
  const m = xml.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`));
  return m ? m[1].trim() : '';
};

for (const item of $input.all()) {
  const j = item.json || {};
  if (j.error) { error = String(j.error.message || j.error); continue; }
  const xml = typeof j.data === 'string' ? j.data : '';
  if (!xml.includes('<feed')) { if (xml) error = 'Response was not an Atom feed'; continue; }

  for (const entry of xml.split('<entry>').slice(1)) {
    fetched++;
    const authors = [...entry.matchAll(/<name>([^<]+)<\/name>/g)].map((m) => m[1].trim());
    const absLink = (entry.match(/<link[^>]*rel="alternate"[^>]*href="([^"]+)"/) || entry.match(/<id>([^<]+)<\/id>/) || [])[1] || '';
    const categories = [...entry.matchAll(/<category[^>]*term="([^"]+)"/g)].map((m) => m[1]);
    const paper = {
      id: tag(entry, 'id'),
      title: tag(entry, 'title'),
      summary: tag(entry, 'summary'),
      published: tag(entry, 'published'),
      updated: tag(entry, 'updated'),
      authors,
      categories,
    };
    out.push({
      json: {
        _type: 'record',
        source_type: 'research_api',
        feed_id: 'arxiv_grounding_agents',
        source_name: 'arXiv',
        focus_hint: 'AI',
        title: paper.title,
        summary: paper.summary,
        author: authors.length > 3 ? `${authors.slice(0, 3).join(', ')} et al.` : authors.join(', '),
        url: absLink.replace(/^http:\/\//, 'https://'),
        published_raw: paper.published,
        engagement_points: null,
        engagement_comments: null,
        raw: paper,
      },
    });
  }
}

out.push({ json: {
  _type: 'status', source_type: 'research_api', feed_id: 'arxiv_grounding_agents', fetched,
  status: error ? 'unavailable' : fetched ? 'ok' : 'empty',
  message: error ? `Source unavailable: ${error}` : fetched ? '' : 'Query returned no papers',
}});
return out;

// Source 3 — Hacker News (Algolia search API). No key.
// Practitioner signal: what engineers are actually discussing.
// Only stories inside the window with >20 points, to skip low-signal posts.
const cfg = $('Run config').first().json;
const queries = [
  { feed_id: 'hn_ai_agents',    q: 'AI agents' },
  { feed_id: 'hn_agentic',      q: 'agentic' },
  { feed_id: 'hn_evals',        q: 'evals' },
  { feed_id: 'hn_ai_safety',    q: 'AI safety' },
  { feed_id: 'hn_hallucination', q: 'hallucination' },
];

return queries.map(({ feed_id, q }) => ({
  json: {
    feed_id,
    query: q,
    url:
      'https://hn.algolia.com/api/v1/search?tags=story&hitsPerPage=20' +
      '&query=' + encodeURIComponent(q) +
      '&numericFilters=' + encodeURIComponent(`points>20,created_at_i>${cfg.since_unix}`),
  },
}));

// Normalize Hacker News (Algolia JSON) → common record shape.
// Each input item is one query's response; the stories are in .hits.
const queries = $('HN query list').all().map((i) => i.json);

const out = [];
const stats = Object.fromEntries(queries.map((q) => [q.feed_id, { fetched: 0, error: null }]));

for (const item of $input.all()) {
  const { _feed, ...j } = item.json || {};
  const q = _feed || queries[0];
  if (j.error) { stats[q.feed_id].error = String(j.error.message || j.error); continue; }
  for (const h of j.hits || []) {
    stats[q.feed_id].fetched++;
    const discussion = `https://news.ycombinator.com/item?id=${h.objectID}`;
    out.push({
      json: {
        _type: 'record',
        source_type: 'community_api',
        feed_id: q.feed_id,
        source_name: 'Hacker News',
        focus_hint: 'AI',
        title: h.title,
        summary: '',
        author: h.author || '',
        url: h.url || discussion,
        discussion_url: discussion,
        published_raw: h.created_at || '',
        engagement_points: h.points ?? null,
        engagement_comments: h.num_comments ?? null,
        raw: h,
      },
    });
  }
}

for (const q of queries) {
  const s = stats[q.feed_id];
  out.push({ json: {
    _type: 'status', source_type: 'community_api', feed_id: q.feed_id, fetched: s.fetched,
    status: s.error ? 'unavailable' : s.fetched ? 'ok' : 'empty',
    message: s.error ? `Source unavailable: ${s.error}` : s.fetched ? '' : 'Query returned no stories',
  }});
}
return out;

// Tag each response with the feed it came from.
// The loop fetches one feed per run, so run N belongs to feed N in the list.
// Tagging here means every record — and every error — is credited to the right feed.
const feeds = $('HN query list').all();
const feed = feeds[$runIndex]?.json;
if (!feed) throw new Error(`No feed at position ${$runIndex} in HN query list`);
return $input.all().map((i) => ({ json: { ...i.json, _feed: feed } }));

// Source 4 — NewsAPI (free tier: 100 requests/day, articles up to ~30 days old).
// The key is read from the NEWSAPI_KEY environment variable (set in .env).
// If the key is missing, the request fails cleanly and the run carries on
// with the other sources — the quality report marks NewsAPI "unavailable".
const cfg = $('Run config').first().json;
const from = new Date(Math.max(new Date(cfg.since_iso).getTime(), Date.now() - 29 * 86400000))
  .toISOString().slice(0, 10);

// Only check whether a key exists; the key itself is read by the HTTP node's
// header expression so it never lands in item data or saved files.
let hasKey = false;
try { hasKey = Boolean($env.NEWSAPI_KEY); } catch (e) { hasKey = false; }

const queries = [
  { feed_id: 'newsapi_ai',    focus_hint: 'AI',    pageSize: 40, q: '"AI agents" OR "agentic AI" OR "AI hallucination" OR "retrieval-augmented generation"' },
  { feed_id: 'newsapi_weave', focus_hint: 'Weave', pageSize: 20, q: '"Weave Communications"' },
];

return queries.map(({ feed_id, focus_hint, pageSize, q }) => ({
  json: {
    feed_id,
    focus_hint,
    has_key: hasKey,
    url:
      'https://newsapi.org/v2/everything?language=en&sortBy=relevancy' +
      `&pageSize=${pageSize}&from=${from}&q=` + encodeURIComponent(q),
  },
}));

// Normalize NewsAPI → common record shape.
// A missing/invalid key or a rate limit comes back as an error item;
// it is logged as "unavailable" and never stops the run.
const queries = $('NewsAPI query list').all().map((i) => i.json);

const out = [];
const stats = Object.fromEntries(queries.map((q) => [q.feed_id, { fetched: 0, error: null }]));

for (const item of $input.all()) {
  const { _feed, ...j } = item.json || {};
  const q = _feed || queries[0];
  if (!q.has_key) { stats[q.feed_id].error = 'NEWSAPI_KEY not set in .env (optional source skipped)'; continue; }
  if (j.error || j.status === 'error') {
    stats[q.feed_id].error = String(j.message || j.error?.message || j.error || 'request failed');
    continue;
  }
  for (const a of j.articles || []) {
    if (a.title === '[Removed]') continue; // NewsAPI placeholder for deleted articles
    stats[q.feed_id].fetched++;
    out.push({
      json: {
        _type: 'record',
        source_type: 'news_api',
        feed_id: q.feed_id,
        source_name: a.source?.name || 'NewsAPI',
        focus_hint: q.focus_hint,
        title: a.title,
        summary: a.description || '',
        author: a.author || '',
        url: a.url,
        published_raw: a.publishedAt || '',
        engagement_points: null,
        engagement_comments: null,
        raw: a,
      },
    });
  }
}

for (const q of queries) {
  const s = stats[q.feed_id];
  out.push({ json: {
    _type: 'status', source_type: 'news_api', feed_id: q.feed_id, fetched: s.fetched,
    status: s.error ? 'unavailable' : s.fetched ? 'ok' : 'empty',
    message: s.error ? `Source unavailable: ${s.error}` : s.fetched ? '' : 'Query returned no articles',
  }});
}
return out;

// Tag each response with the feed it came from.
// The loop fetches one feed per run, so run N belongs to feed N in the list.
// Tagging here means every record — and every error — is credited to the right feed.
const feeds = $('NewsAPI query list').all();
const feed = feeds[$runIndex]?.json;
if (!feed) throw new Error(`No feed at position ${$runIndex} in NewsAPI query list`);
return $input.all().map((i) => ({ json: { ...i.json, _feed: feed } }));

// Validate & Clean — every record either passes every check or is rejected
// with a written reason. Nothing is dropped silently.
//
// Output: one item per candidate record with _status = kept | rejected | trimmed,
// plus the source status rows passed through for the quality report.
//   rejected = failed a quality check (missing field, bad date, duplicate, off-topic)
//   trimmed  = passed every check but cut to keep the dataset balanced (per-feed cap)

const cfg = $('Run config').first().json;
const NOW = new Date(cfg.collected_at).getTime();
const DAY = 86400000;
const sinceFor = (r) => NOW - (r.window_days || cfg.lookback_days) * DAY; // brand feeds look back further
const MAX_PER_FEED = 35;        // no single feed may dominate the dataset
const MAX_LEGAL_NOTICES = 5;    // law-firm "shareholder alert" boilerplate adds little new signal
const SUMMARY_MAX = 400;

// ---------- text helpers ----------
const decode = (s) => s
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(+n))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16)))
  .replace(/&nbsp;/g, ' ').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'")
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&');
const clean = (s) => decode(decode(String(s ?? '')).replace(/<[^>]*>/g, ' '))
  .replace(/[​-‍﻿]/g, '').replace(/\s+/g, ' ').trim();
const truncate = (s, n) => (s.length <= n ? s : s.slice(0, s.lastIndexOf(' ', n - 1)).replace(/[,;:.\s]+$/, '') + '…');
const fingerprint = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();

// FNV-1a → stable 8-char id, so the same article gets the same id on every run
const hash8 = (s) => {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return (h >>> 0).toString(16).padStart(8, '0');
};

// Same article, different URL spellings → one key. (No URL class: the n8n
// Code sandbox doesn't provide it, so this is plain string handling.)
const canonicalUrl = (u) => {
  const m = String(u || '').trim().match(/^https?:\/\/([^/?#]+)([^?#]*)(\?[^#]*)?/i);
  if (!m) return null;
  const host = m[1].toLowerCase().replace(/^www\./, '');
  const path = m[2].replace(/\/+$/, '');
  const query = (m[3] || '').slice(1).split('&')
    .filter((p) => p && !/^(utm_|fbclid|gclid|mc_|ref=|cmpid|oc=)/i.test(p)).join('&');
  const arxiv = (host + path).match(/arxiv\.org\/(?:abs|pdf)\/(\d{4}\.\d{4,5})/);
  if (arxiv) return `arxiv.org/abs/${arxiv[1]}`;   // v1/v2 of the same paper are one record
  return host + path + (query ? `?${query}` : '');
};

// ---------- topic rules (transparent: matched words are saved on the record) ----------
const TOPICS = [
  ['rag_grounding',   /retrieval[- ]augmented|\bRAG\b|grounding|grounded|hallucinat\w*|faithful\w*|fact[- ]check\w*|citations?\b/gi],
  ['ai_agents',       /\bagent(?:s|ic)?\b|multi-agent|autonomous|copilot/gi],
  ['ai_evaluation',   /\bevals?\b|evaluation|benchmark\w*|accuracy|reliab\w*/gi],
  ['ai_trust_safety', /safety|\btrust\w*|governance|regulat\w*|security|privacy|\bbias\b|rogue|lawsuit|copyright/gi],
  ['ai_data_analytics', /analytics|data (?:quality|engineering|warehouse|pipeline)s?|business intelligence|snowflake|databricks/gi],
  ['ai_industry',     /\bA\.?I\.?\b|artificial intelligence|\bLLMs?\b|machine learning|language models?|OpenAI|Anthropic|Gemini|\bGPT|ChatGPT|Claude|Copilot|DeepMind|Grok|Llama|Mistral|Perplexity|Nvidia|chatbots?/gi],
];
const WEAVE = /Weave Communications|\bWEAV\b|getweave|\bWeave\b/gi;
// v2: Weave's direct competitors. Case-sensitive on purpose ("Podium" the company, not an F1 podium);
// whatever still slips through is caught by the AI relevance check downstream.
const COMPETITORS = [
  ['Podium', /\bPodium\b/], ['Birdeye', /\bBirdeye\b/], ['NexHealth', /\bNexHealth\b/],
  ['Solutionreach', /\bSolution[Rr]each\b/], ['RevenueWell', /\bRevenueWell\b/], ['Lighthouse 360', /\bLighthouse 360\b/],
];
const LEGAL = /shareholder alert|investigat\w* whether|fair price|\bLLP\b|law firm|class action|Halper Sadeh|Brodsky|Ademi|Monteverde|Kahn Swick/i;

function classify(r, text) {
  const matched = new Set();
  let topic = null;
  const isWeave = (r.focus_hint === 'Weave' && /weave/i.test(text)) || /Weave Communications|\bWEAV\b|getweave/i.test(text);
  if (isWeave) { topic = 'weave_brand'; (text.match(WEAVE) || []).forEach((m) => matched.add(m)); }
  const rival = isWeave ? null : COMPETITORS.find(([, re]) => re.test(text));
  if (rival) { topic = 'competitor_brand'; matched.add(rival[0]); }
  if (!isWeave && !rival && r.focus_hint === 'Competitor') return { topic: null, focus: 'Competitor', entity: '', signal: 'news', matched: [] };
  for (const [name, re] of TOPICS) {
    const m = text.match(re);
    if (m) { if (!topic) topic = name; m.forEach((w) => matched.add(w.toLowerCase())); }
  }
  let signal = { news_rss: 'news', news_api: 'news', research_api: 'research_paper', community_api: 'community_discussion' }[r.source_type];
  if (isWeave) {
    // Brand events: what kind of thing happened to Weave (for reputation monitoring)
    if (LEGAL.test(text)) signal = 'legal_notice';
    else if (/acqui\w*|merger|antitrust|buyout|takeover|to be acquired/i.test(text)) signal = 'm_and_a';
    else if (/downgrade\w*|upgrade\w*|price target|rating|analyst\w*|fair value/i.test(text)) signal = 'analyst_rating';
    else if (/shares withheld|stock sale|insider|RSU|Form 4/i.test(text)) signal = 'insider_trade';
    else if (/earnings|revenue|EPS|income|guidance|quarter/i.test(text)) signal = 'financials';
  }
  if (r.feed_id.startsWith('reddit_')) signal = 'community_discussion';
  if (signal === 'news' && /businesswire|prnewswire|globenewswire|accesswire/i.test(r.source_name + ' ' + r.url)) signal = 'press_release';
  const entity = isWeave ? 'Weave' : rival ? rival[0] : '';
  return { topic, focus: isWeave ? 'Weave' : rival ? 'Competitor' : 'AI', entity, signal, matched: [...matched].slice(0, 6) };
}

// ---------- process ----------
const items = $input.all().map((i) => i.json);
const statusRows = items.filter((j) => j._type === 'status');
const records = items.filter((j) => j._type === 'record');

// Priority: primary publishers and APIs first, aggregators last, so when the
// same story appears twice the better-attributed copy is the one kept.
const PRIORITY = { news_rss: 1, research_api: 1, community_api: 2, news_api: 3 };
const prio = (r) => (r.feed_id.startsWith('gnews_') ? 4 : r.feed_id.startsWith('reddit_') ? 2 : PRIORITY[r.source_type] || 5);

const candidates = records.map((r) => {
  let title = clean(r.title);
  let sourceName = clean(r.source_name);
  let aggregator = '';
  // Google News titles look like "Headline - Publisher": split them.
  if (r.feed_id.startsWith('gnews_')) {
    aggregator = 'Google News';
    const cut = title.lastIndexOf(' - ');
    if (cut > 0) { sourceName = title.slice(cut + 3).trim(); title = title.slice(0, cut).trim(); }
  }
  let summary = clean(r.summary);
  if (fingerprint(summary).startsWith(fingerprint(title)) || summary.length < 25) summary = '';
  const t = Date.parse(r.published_raw);
  return {
    r, title, sourceName, aggregator,
    summary: summary ? truncate(summary, SUMMARY_MAX) : '',
    author: clean(Array.isArray(r.author) ? r.author.join(', ') : r.author),
    url: String(r.url || '').trim(),
    ts: Number.isFinite(t) ? t : NaN,
  };
}).sort((a, b) => prio(a.r) - prio(b.r) || b.ts - a.ts);

const seenUrl = new Map();
const seenTitle = new Map();
const perFeed = {};
let legalCount = 0;
const out = [];

for (const c of candidates) {
  const r = c.r;
  const reasons = [];
  if (!c.title || c.title.length < 8) reasons.push('missing_title');
  if (!/^https?:\/\/\S+\.\S+/.test(c.url)) reasons.push('invalid_url');
  if (!c.sourceName) reasons.push('missing_source');
  if (!Number.isFinite(c.ts)) reasons.push('invalid_date');
  else if (c.ts > NOW + 86400000) reasons.push('future_date');
  else if (c.ts < sinceFor(r)) reasons.push('outside_window');

  const text = `${c.title} ${c.summary}`;
  const cls = classify(r, text);
  if (!reasons.length && !cls.topic) reasons.push('off_topic');

  const canon = canonicalUrl(c.url);
  const fp = fingerprint(c.title);
  if (!reasons.length) {
    if (seenUrl.has(canon)) reasons.push(`duplicate_url_of_${seenUrl.get(canon)}`);
    else if (seenTitle.has(fp)) reasons.push(`duplicate_title_of_${seenTitle.get(fp)}`);
  }

  const record_id = 'GL-' + hash8(canon || c.url || c.title);
  let status = reasons.length ? 'rejected' : 'kept';
  let reason = reasons.map((x) => x.replace(/_of_GL-\w+$/, '')).join('|');
  let reasonDetail = reasons.join('|');

  if (status === 'kept') {
    seenUrl.set(canon, record_id);
    seenTitle.set(fp, record_id);
    perFeed[r.feed_id] = (perFeed[r.feed_id] || 0) + 1;
    if (perFeed[r.feed_id] > MAX_PER_FEED) { status = 'trimmed'; reason = reasonDetail = 'feed_cap'; }
    else if (cls.signal === 'legal_notice' && ++legalCount > MAX_LEGAL_NOTICES) { status = 'trimmed'; reason = reasonDetail = 'legal_notice_cap'; }
  }

  const iso = Number.isFinite(c.ts) ? new Date(c.ts).toISOString() : '';
  const filled = [c.title, c.url, iso, c.sourceName, c.summary, c.author, cls.topic].filter(Boolean).length;

  out.push({ json: {
    _type: 'record',
    _status: status,
    _reason: reason,
    _reason_detail: reasonDetail,
    record_id,
    published_date: iso.slice(0, 10),
    title: c.title,
    summary: c.summary,
    topic: cls.topic || '',
    focus: cls.focus,
    entity: cls.entity,
    signal_type: cls.signal,
    source_name: c.sourceName,
    source_type: r.source_type,
    collected_via: r.feed_id,
    aggregator: c.aggregator,
    author: c.author,
    url: c.url,
    discussion_url: r.discussion_url || '',
    engagement_points: r.engagement_points ?? '',
    engagement_comments: r.engagement_comments ?? '',
    matched_keywords: cls.matched.join('; '),
    completeness_pct: Math.round((filled / 7) * 100),
    published_at_utc: iso,
    collected_at: cfg.collected_at,
    run_id: cfg.run_id,
  }});
}

return [...out, ...statusRows.map((s) => ({ json: s }))];

// Final dataset — kept records only, internal fields removed, newest first.
// Runs post-condition checks: if any fail, the run stops with a clear error
// instead of writing a bad file.
const rows = $input.all()
  .map((i) => i.json)
  .filter((j) => j._type === 'record' && j._status === 'kept')
  .sort((a, b) => b.published_at_utc.localeCompare(a.published_at_utc))
  .map(({ _type, _status, _reason, _reason_detail, ...rest }) => rest);

const problems = [];
const ids = new Set(), urls = new Set();
for (const r of rows) {
  if (!r.title || !r.url || !r.source_name || !r.published_date) problems.push(`${r.record_id}: missing critical field`);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(r.published_date)) problems.push(`${r.record_id}: date not YYYY-MM-DD`);
  if (ids.has(r.record_id)) problems.push(`${r.record_id}: duplicate record_id`);
  if (urls.has(r.url)) problems.push(`${r.record_id}: duplicate url`);
  ids.add(r.record_id); urls.add(r.url);
}
if (problems.length) throw new Error('Post-condition checks failed:\n' + problems.slice(0, 20).join('\n'));
if (rows.length === 0) throw new Error('No records passed validation — check the source status rows in the quality report.');

return rows.map((json) => ({ json }));

// Quality report — the run's numbers, as JSON (for machines) and Markdown (for people).
const cfg = $('Run config').first().json;
const all = $input.all().map((i) => i.json);
const status = all.filter((j) => j._type === 'status');
const recs = all.filter((j) => j._type === 'record');
const kept = recs.filter((r) => r._status === 'kept');
const rejected = recs.filter((r) => r._status === 'rejected');
const trimmed = recs.filter((r) => r._status === 'trimmed');

const count = (arr, key) => arr.reduce((m, r) => ((m[r[key]] = (m[r[key]] || 0) + 1), m), {});
const pct = (n, d) => (d ? Math.round((n / d) * 1000) / 10 : 0);

const collected = recs.length;
const duplicates = rejected.filter((r) => r._reason.startsWith('duplicate')).length;
const qualityFails = rejected.length - duplicates;
const unique = collected - duplicates;

const ENRICH = ['summary', 'author'];
const fieldFill = Object.fromEntries(
  ['record_id', 'title', 'url', 'published_date', 'source_name', 'topic', 'summary', 'author']
    .map((f) => [f, pct(kept.filter((r) => r[f] !== '' && r[f] != null).length, kept.length)])
);
const fullyComplete = kept.filter((r) => ENRICH.every((f) => r[f])).length;

// Per-source table: what each feed returned and what survived
const perFeed = {};
for (const s of status) perFeed[s.feed_id] = { source_type: s.source_type, status: s.status, message: s.message, fetched: s.fetched, kept: 0, rejected: 0, trimmed: 0 };
for (const r of recs) {
  const f = perFeed[r.collected_via] || (perFeed[r.collected_via] = { source_type: r.source_type, status: 'ok', message: '', fetched: 0, kept: 0, rejected: 0, trimmed: 0 });
  f[r._status]++;
}

const dates = kept.map((r) => r.published_date).sort();
const checks = [
  ['Every kept record has title, URL, source and date', kept.every((r) => r.title && r.url && r.source_name && r.published_date)],
  ['Every date is YYYY-MM-DD', kept.every((r) => /^\d{4}-\d{2}-\d{2}$/.test(r.published_date))],
  ['No date in the future', kept.every((r) => Date.parse(r.published_at_utc) <= Date.parse(cfg.collected_at) + 86400000)],
  ['No duplicate record IDs', new Set(kept.map((r) => r.record_id)).size === kept.length],
  ['No duplicate URLs', new Set(kept.map((r) => r.url)).size === kept.length],
  ['Every record has a topic', kept.every((r) => r.topic)],
  ['At least 3 source systems contributed', new Set(kept.map((r) => r.source_type)).size >= 3],
  ['Record count within 50–400 target', kept.length >= 50 && kept.length <= 400],
].map(([check, pass]) => ({ check, pass }));

const report = {
  run_id: cfg.run_id,
  collected_at: cfg.collected_at,
  window: { lookback_days: cfg.lookback_days, since: cfg.since_iso.slice(0, 10), until: cfg.run_date },
  totals: {
    collected, duplicates_removed: duplicates, failed_quality_checks: qualityFails,
    unique_records: unique, trimmed_for_balance: trimmed.length, kept: kept.length,
    quality_pass_rate_pct: pct(unique - qualityFails, unique),
    fully_complete_records: fullyComplete, fully_complete_pct: pct(fullyComplete, kept.length),
  },
  kept_by: {
    source_type: count(kept, 'source_type'), focus: count(kept, 'focus'),
    topic: count(kept, 'topic'), signal_type: count(kept, 'signal_type'),
  },
  field_completeness_pct: fieldFill,
  date_range: { earliest: dates[0] || null, latest: dates[dates.length - 1] || null },
  rejects_by_reason: count(rejected, '_reason'),
  trimmed_by_reason: count(trimmed, '_reason'),
  sources: perFeed,
  checks,
  all_checks_passed: checks.every((c) => c.pass),
};

// ---------- Markdown ----------
const t = report.totals;
const row = (cells) => `| ${cells.join(' | ')} |`;
const table = (head, rows) => [row(head), row(head.map(() => '---')), ...rows.map(row)].join('\n');
const obj = (o) => Object.entries(o).sort((a, b) => b[1] - a[1]);

const md = `# Groundline — Data Quality Report

**Run:** \`${cfg.run_id}\` · **Collected:** ${cfg.collected_at.slice(0, 16).replace('T', ' ')} UTC · **Window:** ${report.window.since} → ${report.window.until} (${cfg.lookback_days} days)

## Summary

${table(['Metric', 'Value'], [
  ['Records collected (all sources)', t.collected],
  ['Duplicates removed', t.duplicates_removed],
  ['Unique records', t.unique_records],
  ['Failed a quality check', t.failed_quality_checks],
  ['**Quality pass rate** (unique records passing every check)', `**${t.quality_pass_rate_pct}%**`],
  ['Trimmed for balance (passed, but over a per-feed cap)', t.trimmed_for_balance],
  ['**Records in final dataset**', `**${t.kept}**`],
  ['Records with every optional field (summary + author)', `${t.fully_complete_records} (${t.fully_complete_pct}%)`],
  ['Date range of kept records', `${report.date_range.earliest} → ${report.date_range.latest}`],
])}

## Automated checks

${table(['Check', 'Result'], checks.map((c) => [c.check, c.pass ? '✅ pass' : '❌ fail']))}

## Sources

${table(['Feed', 'Type', 'Status', 'Fetched', 'Kept', 'Rejected', 'Trimmed', 'Note'],
  Object.entries(perFeed).map(([k, v]) => [`\`${k}\``, v.source_type, v.status === 'ok' ? '🟢 ok' : v.status === 'empty' ? '🟡 empty' : '🔴 unavailable', v.fetched, v.kept, v.rejected, v.trimmed, v.message || '']))}

## Field completeness (kept records)

${table(['Field', 'Filled'], Object.entries(fieldFill).map(([k, v]) => [`\`${k}\``, `${v}%`]))}

Critical fields (title, URL, date, source) are enforced at 100%. \`summary\` and \`author\` are optional: Hacker News stories have no summary, and many news feeds omit the author.

## Why records were rejected

${table(['Reason', 'Count'], obj(report.rejects_by_reason).map(([k, v]) => [`\`${k}\``, v]))}

${trimmed.length ? `Trimmed for balance: ${obj(report.trimmed_by_reason).map(([k, v]) => `\`${k}\` ${v}`).join(', ')}.` : ''}

## Dataset composition

${table(['By focus', 'Records'], obj(report.kept_by.focus))}

${table(['By source type', 'Records'], obj(report.kept_by.source_type))}

${table(['By topic', 'Records'], obj(report.kept_by.topic))}

${table(['By signal type', 'Records'], obj(report.kept_by.signal_type))}
`;

return [{ json: { report_json: JSON.stringify(report, null, 2), markdown: md, all_checks_passed: report.all_checks_passed, kept: kept.length } }];

// Rejects log — every record that did not make the dataset, and why.
// Makes the filter auditable: anyone can check nothing good was thrown away.
return $input.all()
  .map((i) => i.json)
  .filter((j) => j._type === 'record' && j._status !== 'kept')
  .map((j) => ({ json: {
    record_id: j.record_id,
    status: j._status,
    reason: j._reason_detail,
    published_date: j.published_date,
    title: j.title,
    source_name: j.source_name,
    collected_via: j.collected_via,
    url: j.url,
  }}));

// Raw snapshot — every record exactly as each source returned it (under .raw),
// saved once per run. "Collect once, reuse forever": cleaning can be re-run
// against this file without hitting any source again.
const cfg = $('Run config').first().json;
const items = $input.all().map((i) => i.json);
const snapshot = {
  run_id: cfg.run_id,
  collected_at: cfg.collected_at,
  sources: items.filter((j) => j._type === 'status'),
  records: items.filter((j) => j._type === 'record'),
};
return [{ json: { snapshot_json: JSON.stringify(snapshot, null, 2), file_name: `raw_${cfg.run_id}.json` } }];

// Load the analysis cache written by the previous run.
// Records the AI has already judged (same record_id, same prompt version) are
// reused instead of paid for again. A missing or corrupt cache is not an error:
// the run simply starts cold and says so in the run metrics.
let cache = { analysis: {}, alerted: {} };
let status = 'cold_start: no cache file yet';
const item = $input.first();
try {
  if (item && item.binary && item.binary.data) {
    const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
    const parsed = JSON.parse(buf.toString('utf8'));
    cache = { analysis: parsed.analysis || {}, alerted: parsed.alerted || {} };
    status = `loaded: ${Object.keys(cache.analysis).length} analyses, ${Object.keys(cache.alerted).length} alerted records`;
  } else if (item && item.json && item.json.error) {
    status = 'cold_start: ' + String(item.json.error.message || item.json.error).slice(0, 120);
  }
} catch (e) {
  status = 'cold_start: cache unreadable (' + e.message.slice(0, 80) + ') — it will be rebuilt';
}
return [{ json: { cache, cache_status: status } }];

// ─── Groundline AI client ───────────────────────────────────────────────────
// Shared by every AI node. scripts/build_workflow.py pastes this file at the top
// of each AI Code node, so the retry / fallback / cost rules live in one place.
//
// Provider chain: Muse Spark (Meta Model API) → Gemini (backup) → caller's rule fallback.
// Both providers speak the OpenAI Chat Completions format, so one client covers both.
//
// What it handles:
//   429 / 5xx / timeout / network  → retry with exponential backoff + jitter (honours Retry-After)
//   400 "unsupported parameter"    → retry once without the optional params
//   401 / 403 / 404                → don't retry; move to the next provider
//   reply is not valid JSON, or fails the caller's schema check → one "repair" round-trip
//   every provider failed          → throws AIError; the caller falls back to rules
// Every call is metered: tokens, cost, latency, retries, provider used.
const __http = this.helpers.httpRequest.bind(this.helpers);

const AI = (() => {
  const env = (k, d = '') => { try { const v = $env[k]; return v === undefined || v === null || v === '' ? d : String(v); } catch (e) { return d; } };
  const real = (k) => k && !/^your_|_here$|^changeme$/i.test(k);

  // USD per 1M tokens. Muse: Meta Model API list price. Gemini: free tier = $0.
  const PROVIDERS = [
    { id: 'muse', label: 'Muse Spark', base: env('MUSE_BASE_URL', 'https://api.meta.ai/v1'), key: env('MUSE_API_KEY'),
      model: env('MUSE_MODEL', 'muse-spark-1.3'), price: { in: +env('MUSE_PRICE_IN', '1.25'), out: +env('MUSE_PRICE_OUT', '4.25') } },
    { id: 'gemini', label: 'Gemini', base: env('GEMINI_BASE_URL', 'https://generativelanguage.googleapis.com/v1beta/openai'), key: env('GEMINI_API_KEY'),
      model: env('GEMINI_MODEL', 'gemini-2.5-flash'), price: { in: +env('GEMINI_PRICE_IN', '0'), out: +env('GEMINI_PRICE_OUT', '0') } },
  ].filter((p) => real(p.key));

  const MAX_TRIES = +env('AI_MAX_TRIES', '4');
  const BASE_DELAY_MS = +env('AI_BASE_DELAY_MS', '1500');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  const metrics = { calls: 0, ok: 0, failed: 0, retries: 0, repairs: 0, provider_fallbacks: 0,
    tokens_in: 0, tokens_out: 0, cost_usd: 0, latency_ms: [], by_provider: {}, errors: [] };

  class AIError extends Error { constructor(msg, kind) { super(msg); this.kind = kind; } }

  function parseJson(text) {
    if (typeof text !== 'string') throw new AIError('empty reply', 'malformed');
    let t = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
    try { return JSON.parse(t); } catch (e) { /* fall through */ }
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { /* fall through */ } }
    throw new AIError('reply is not valid JSON: ' + t.slice(0, 120), 'malformed');
  }

  const statusOf = (e) => e.status || e.httpCode || e.statusCode || (e.response && e.response.status) || 0;
  const retryAfterMs = (e) => {
    const h = (e.response && e.response.headers) || {};
    const v = h['retry-after'] || h['Retry-After'];
    return v && Number.isFinite(+v) ? Math.min(+v * 1000, 30000) : 0;
  };

  async function post(p, body, timeoutMs) {
    const t0 = Date.now();
    const res = await __http({
      method: 'POST', url: p.base.replace(/\/$/, '') + '/chat/completions',
      headers: { Authorization: `Bearer ${p.key}`, 'Content-Type': 'application/json' },
      body, json: true, timeout: timeoutMs,
    });
    return { res, ms: Date.now() - t0 };
  }

  // One provider, with retries. Returns parsed + validated JSON or throws.
  async function callProvider(p, task) {
    const messages = [{ role: 'system', content: task.system }, { role: 'user', content: task.user }];
    let optional = { response_format: { type: 'json_object' }, reasoning_effort: task.effort || 'low' };
    let repaired = false;
    for (let attempt = 1; attempt <= MAX_TRIES; attempt++) {
      metrics.calls++;
      try {
        const body = { model: p.model, messages, max_completion_tokens: task.maxTokens || 4000, temperature: task.temperature ?? 0.2, ...optional };
        const { res, ms } = await post(p, body, task.timeoutMs || 90000);
        const u = res.usage || {};
        const tin = u.prompt_tokens || 0, tout = u.completion_tokens || 0;
        const cost = (tin * p.price.in + tout * p.price.out) / 1e6;
        metrics.tokens_in += tin; metrics.tokens_out += tout; metrics.cost_usd += cost; metrics.latency_ms.push(ms);
        const bp = (metrics.by_provider[p.id] = metrics.by_provider[p.id] || { calls: 0, tokens_in: 0, tokens_out: 0, cost_usd: 0 });
        bp.calls++; bp.tokens_in += tin; bp.tokens_out += tout; bp.cost_usd += cost;

        const text = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
        let data, problem;
        try { data = parseJson(text); problem = task.validate ? task.validate(data) : null; }
        catch (e) { problem = e.message; }
        if (!problem) { metrics.ok++; return { data, provider: p.id, model: p.model, ms, tokens_in: tin, tokens_out: tout, cost_usd: cost, attempts: attempt }; }

        // Malformed or off-schema reply: show the model its own mistake once.
        if (repaired) throw new AIError(`invalid reply after repair: ${problem}`, 'malformed');
        repaired = true; metrics.repairs++;
        messages.push({ role: 'assistant', content: String(text || '').slice(0, 6000) });
        messages.push({ role: 'user', content: `Your reply was rejected: ${problem}. Reply again with ONLY the corrected JSON object, nothing else.` });
        continue;
      } catch (e) {
        if (e instanceof AIError) throw e;
        const st = statusOf(e);
        const msg = String(e.message || e).slice(0, 200);
        if (st === 400 && optional.response_format && /response_format|reasoning|unsupported|unknown/i.test(JSON.stringify((e.response && e.response.data) || msg))) {
          optional = {}; metrics.retries++; continue;          // provider rejects an optional param → drop it
        }
        if ([401, 403, 404].includes(st)) throw new AIError(`${p.label} ${st}: ${msg}`, 'auth');
        const retryable = !st || st === 408 || st === 409 || st === 429 || st >= 500;
        if (!retryable || attempt === MAX_TRIES) throw new AIError(`${p.label} ${st || 'network'}: ${msg}`, st === 429 ? 'rate_limit' : 'unavailable');
        metrics.retries++;
        const backoff = BASE_DELAY_MS * 2 ** (attempt - 1) + Math.floor(Math.random() * 400);
        await sleep(Math.max(backoff, retryAfterMs(e)));
      }
    }
    throw new AIError(`${p.label}: retries exhausted`, 'unavailable');
  }

  // Public: try each provider in order. task = { name, system, user, validate, effort, maxTokens, timeoutMs }
  async function complete(task) {
    if (!PROVIDERS.length) {
      metrics.failed++;
      metrics.errors.push({ task: task.name, error: 'no AI provider configured (set MUSE_API_KEY or GEMINI_API_KEY in .env)' });
      throw new AIError('no AI provider configured', 'no_provider');
    }
    // task.prefer lets a caller pick a different model first — the fact-checker uses this
    // so that, when both keys exist, a second model checks the first one's work.
    const order = task.prefer ? [...PROVIDERS].sort((a, b) => (b.id === task.prefer) - (a.id === task.prefer)) : PROVIDERS;
    let last;
    for (let i = 0; i < order.length; i++) {
      try { return await callProvider(order[i], task); }
      catch (e) {
        last = e;
        metrics.errors.push({ task: task.name, provider: order[i].id, kind: e.kind || 'error', error: String(e.message).slice(0, 240) });
        if (i < order.length - 1) metrics.provider_fallbacks++;
      }
    }
    metrics.failed++;
    throw last;
  }

  // Run async jobs with a concurrency cap (keeps us under provider rate limits).
  async function pool(jobs, limit) {
    const out = new Array(jobs.length); let next = 0;
    const worker = async () => { while (next < jobs.length) { const i = next++; out[i] = await jobs[i](); } };
    await Promise.all(Array.from({ length: Math.min(limit, jobs.length) }, worker));
    return out;
  }

  function summary() {
    const l = [...metrics.latency_ms].sort((a, b) => a - b);
    const pct = (q) => (l.length ? l[Math.min(l.length - 1, Math.floor(q * l.length))] : 0);
    return { ...metrics, latency_ms: undefined, cost_usd: +metrics.cost_usd.toFixed(6),
      latency_p50_ms: pct(0.5), latency_p95_ms: pct(0.95), latency_max_ms: l[l.length - 1] || 0,
      providers_configured: PROVIDERS.map((p) => `${p.id}:${p.model}`) };
  }

  return { complete, pool, summary, AIError, env, providers: PROVIDERS.map((p) => ({ id: p.id, label: p.label, model: p.model })) };
})();
// ─── end AI client ──────────────────────────────────────────────────────────

// ─── Groundline Analyst core ────────────────────────────────────────────────
// Agent 3 from the A2 design ("Analyst"), first half: read every record and judge it.
// Pasted (after ai_client.js) into the "AI Analyst" node of the main workflow AND
// the Analyze API webhook used for scale testing, so both run identical logic.
//
// For each record the AI decides:
//   relevance 0–3      0 = unrelated (an F1 "podium"), 3 = directly about Weave or a competitor
//   entity             which company it is about (or "Market")
//   sentiment −2…+2    tone toward that entity
//   theme / evidence   what kind of event, and whether it was announced, proven, reported or discussed
//   risk_to_weave / opportunity_for_weave   none | low | medium | high  → drives alert routing
//   archetype          which of the 12 brand archetypes the coverage casts the entity as
//   key_fact           one sentence that is stated in the source (used later for fact-checking)
const PROMPT_VERSION = 'analyst-v1';
const ENTITIES = ['Weave', 'Podium', 'Birdeye', 'NexHealth', 'Solutionreach', 'RevenueWell', 'Lighthouse 360', 'Market', 'None'];
const THEMES = ['product', 'ai_strategy', 'pricing', 'customer_experience', 'partnership', 'm_and_a', 'financials',
  'legal_regulatory', 'leadership', 'market_trend', 'other'];
const EVIDENCE = ['announced', 'proven', 'reported', 'discussed'];
const LEVELS = ['none', 'low', 'medium', 'high'];
const ARCHETYPES = ['Innocent', 'Everyman', 'Hero', 'Outlaw', 'Explorer', 'Creator', 'Ruler', 'Magician', 'Lover', 'Caregiver', 'Jester', 'Sage'];

const ANALYST_SYSTEM = `You are the brand-intelligence analyst for Weave Communications (NYSE: WEAV), a customer-communication and payments platform for ~40,000 dental, optometry and veterinary practices. Direct competitors: Podium, Birdeye, NexHealth, Solutionreach, RevenueWell, Lighthouse 360.

You receive news items, papers and community posts. Judge each one ONLY from its title and summary. Never invent facts.

Return JSON: {"items":[{...one object per input item, same order...}]} with exactly these fields:
- "id": the input id, unchanged
- "relevance": 0 = unrelated to Weave's market (e.g. a sports "podium", a fabric "weave"), 1 = general AI/tech background, 2 = adjacent market (AI agents for customer service, SMB software, healthcare practices), 3 = directly about Weave or a named competitor
- "entity": one of ${JSON.stringify(ENTITIES)}. "Market" for industry items, "None" when relevance is 0
- "sentiment": integer -2..2, the tone toward that entity (0 if neutral or relevance 0)
- "theme": one of ${JSON.stringify(THEMES)}
- "evidence": "announced" (company says it), "proven" (research/data), "reported" (journalism), "discussed" (opinion/community)
- "risk_to_weave": one of ${JSON.stringify(LEVELS)}. high = could hurt Weave's reputation, revenue or stock soon (lawsuit, outage, downgrade, a competitor winning Weave's customers)
- "opportunity_for_weave": one of ${JSON.stringify(LEVELS)}. high = a competitor stumbling or a market shift Weave can act on now
- "archetype": which of ${JSON.stringify(ARCHETYPES)} this coverage portrays the entity as, or null if it doesn't portray a brand
- "key_fact": ONE sentence stating the main fact, using only information in the title/summary
- "why": at most 20 words explaining the risk/opportunity rating`;

function validateAnalysis(ids) {
  return (data) => {
    if (!data || !Array.isArray(data.items)) return 'missing "items" array';
    const want = new Set(ids);
    for (const it of data.items) {
      if (!it || !want.has(it.id)) continue;            // unknown ids are ignored, missing ones fall back later
      it.relevance = Math.max(0, Math.min(3, Math.round(+it.relevance)));
      it.sentiment = Math.max(-2, Math.min(2, Math.round(+it.sentiment)));
      if (!Number.isFinite(it.relevance) || !Number.isFinite(it.sentiment)) return `item ${it.id}: relevance/sentiment must be numbers`;
      if (!ENTITIES.includes(it.entity)) return `item ${it.id}: entity must be one of ${ENTITIES.join(', ')}`;
      if (!THEMES.includes(it.theme)) it.theme = 'other';
      if (!EVIDENCE.includes(it.evidence)) it.evidence = 'reported';
      if (!LEVELS.includes(it.risk_to_weave) || !LEVELS.includes(it.opportunity_for_weave)) return `item ${it.id}: risk_to_weave/opportunity_for_weave must be none|low|medium|high`;
      if (it.archetype && !ARCHETYPES.includes(it.archetype)) it.archetype = null;
      if (typeof it.key_fact !== 'string' || it.key_fact.length < 8) return `item ${it.id}: key_fact must be a sentence`;
    }
    const got = data.items.filter((it) => it && want.has(it.id)).length;
    if (got < Math.ceil(ids.length / 2)) return `only ${got} of ${ids.length} ids returned`;
    return null;
  };
}

// Rule-based fallback = the A3 behaviour. Used when every AI provider is down,
// when the AI skipped an item, or when the run's AI budget is used up.
const POS = /\b(launch\w*|record|growth|grow\w*|wins?|award\w*|beat\w*|surge\w*|upgrade\w*|partner\w*|expand\w*|profit\w*|raises?)\b/i;
const NEG = /\b(lawsuit|investigat\w*|downgrade\w*|layoff\w*|breach\w*|outage|decline\w*|miss(?:es|ed)?|loss(?:es)?|fraud|cuts?|drops?|falls?|scrap\w*|shut\w*)\b/i;
function rulesAnalysis(r, reason) {
  const text = `${r.title} ${r.summary || ''}`;
  const sentiment = NEG.test(text) ? -1 : POS.test(text) ? 1 : 0;
  const entity = r.entity || (r.focus === 'AI' ? 'Market' : 'None');
  const themeBySignal = { legal_notice: 'legal_regulatory', m_and_a: 'm_and_a', analyst_rating: 'financials', insider_trade: 'financials',
    financials: 'financials', research_paper: 'market_trend', community_discussion: 'market_trend', press_release: 'product' };
  let risk = 'none';
  if (entity === 'Weave') risk = r.signal_type === 'legal_notice' || (sentiment < 0) ? 'medium' : 'low';
  return {
    relevance: r.entity ? 3 : 1, entity, sentiment,
    theme: themeBySignal[r.signal_type] || 'other',
    evidence: { research_paper: 'proven', community_discussion: 'discussed', press_release: 'announced' }[r.signal_type] || 'reported',
    risk_to_weave: risk, opportunity_for_weave: entity !== 'Weave' && r.entity && sentiment < 0 ? 'low' : 'none',
    archetype: null, key_fact: r.title, why: `keyword rules (${reason})`,
  };
}

// Decision: where does this record go?
function routeFor(a) {
  if (a.relevance >= 2 && (a.risk_to_weave === 'high' || (a.entity === 'Weave' && a.risk_to_weave === 'medium' && a.sentiment <= -2))) return 'urgent_risk';
  if (a.relevance >= 2 && a.opportunity_for_weave === 'high') return 'opportunity';
  if (a.relevance === 0) return 'discard';
  return 'digest';
}

// records: A3-shape records. cache: { [record_id]: { v, a, at } }
async function analyzeRecords(records, opts = {}) {
  const cache = opts.cache || {};
  const BATCH = opts.batchSize || +AI.env('AI_BATCH_SIZE', '10');
  const CONC = opts.concurrency || +AI.env('AI_CONCURRENCY', '3');
  const MAX_AI = opts.maxAI ?? +AI.env('AI_MAX_RECORDS', '400');
  const useCache = opts.useCache !== false;
  const BREAKER = 3;                                     // consecutive failed batches → stop calling AI this run

  const results = new Map();
  const stats = { cache_hits: 0, ai_analyzed: 0, fallback: 0, fallback_reasons: {}, batches: 0, batches_failed: 0, circuit_open: false };
  const fallback = (r, reason) => {
    results.set(r.record_id, { ...rulesAnalysis(r, reason), analysis_source: 'rules_fallback', analysis_note: reason });
    stats.fallback++; stats.fallback_reasons[reason] = (stats.fallback_reasons[reason] || 0) + 1;
  };

  const todo = [];
  for (const r of records) {
    const hit = useCache && cache[r.record_id];
    if (hit && hit.v === PROMPT_VERSION) { results.set(r.record_id, { ...hit.a, analysis_source: 'cache', analysis_note: `cached ${hit.at}` }); stats.cache_hits++; }
    else todo.push(r);
  }
  // Brand records first, then newest — if the budget runs out, background items are the ones skipped.
  todo.sort((a, b) => (b.entity ? 1 : 0) - (a.entity ? 1 : 0) || String(b.published_date).localeCompare(String(a.published_date)));
  const forAI = todo.slice(0, MAX_AI);
  todo.slice(MAX_AI).forEach((r) => fallback(r, 'ai_budget_reached'));

  const batches = [];
  for (let i = 0; i < forAI.length; i += BATCH) batches.push(forAI.slice(i, i + BATCH));
  let consecutiveFails = 0;

  await AI.pool(batches.map((batch) => async () => {
    if (stats.circuit_open) { batch.forEach((r) => fallback(r, 'circuit_open')); return; }
    stats.batches++;
    const ids = batch.map((r) => r.record_id);
    const input = batch.map((r) => ({ id: r.record_id, title: r.title, summary: (r.summary || '').slice(0, 400),
      source: r.source_name, date: r.published_date, type: r.signal_type, hint_entity: r.entity || undefined }));
    try {
      const res = await AI.complete({ name: 'analyze', system: ANALYST_SYSTEM, user: JSON.stringify({ items: input }),
        validate: validateAnalysis(ids), effort: 'low', maxTokens: 400 + 160 * batch.length, timeoutMs: 90000 });
      consecutiveFails = 0;
      const byId = Object.fromEntries(res.data.items.filter((it) => it && ids.includes(it.id)).map((it) => [it.id, it]));
      for (const r of batch) {
        const a = byId[r.record_id];
        if (!a) { fallback(r, 'ai_skipped_item'); continue; }
        const { id, ...analysis } = a;
        results.set(r.record_id, { ...analysis, analysis_source: `ai:${res.provider}`, analysis_note: res.model });
        cache[r.record_id] = { v: PROMPT_VERSION, a: analysis, at: new Date().toISOString().slice(0, 10), by: `${res.provider}:${res.model}` };
        stats.ai_analyzed++;
      }
    } catch (e) {
      stats.batches_failed++;
      consecutiveFails++;
      if (e.kind === 'no_provider' || consecutiveFails >= BREAKER) stats.circuit_open = true;
      batch.forEach((r) => fallback(r, e.kind === 'no_provider' ? 'no_ai_provider' : `ai_error:${e.kind || 'unknown'}`));
    }
  }), CONC);

  const out = records.map((r) => {
    const a = results.get(r.record_id) || { ...rulesAnalysis(r, 'missing'), analysis_source: 'rules_fallback' };
    return { ...r, ...a, route: routeFor(a) };
  });
  return { records: out, stats, cache };
}
// ─── end Analyst core ───────────────────────────────────────────────────────

// AI Analyst — Muse Spark reads every clean record and judges it
// (relevance, entity, sentiment, theme, risk, opportunity, archetype, key fact).
// Logic lives in workflow/lib/analyst_core.js (pasted above by the build script).
//
// Error handling: cache first; batches of 10; 3 batches in parallel; per-batch retries
// and provider fallback inside the AI client; a circuit breaker after 3 failed batches;
// anything the AI could not judge falls back to the A3 keyword rules and is labelled so.
const t0 = Date.now();
const records = $('Final dataset').all().map((i) => i.json);
const loaded = $('Load cache').first().json;
const cache = loaded.cache.analysis;

const { records: out, stats } = await analyzeRecords(records, { cache });

return [
  ...out.map((r) => ({ json: { _type: 'record', ...r } })),
  { json: { _type: 'ai_run', step: 'analyst', prompt_version: PROMPT_VERSION, cache_status: loaded.cache_status,
    stats, ai: AI.summary(), providers: AI.providers, duration_ms: Date.now() - t0,
    cache: { analysis: cache, alerted: loaded.cache.alerted } } },
];

