.tile .v{font-size:26px;font-weight:700;color:var(--ink);line-height:1.1}.tile .l{font-size:12px;color:var(--muted);text-transform:uppercase;letter-spacing:.05em}
.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:18px 20px;margin:12px 0}
ul.claims{margin:0;padding-left:18px}ul.claims li{margin:6px 0}
.cite{display:inline-block;font-size:11px;font-weight:600;color:var(--accent);background:var(--accent-soft);border-radius:4px;padding:0 5px;margin-left:3px;text-decoration:none;vertical-align:1px}
.badge{display:inline-flex;gap:8px;align-items:center;border-radius:999px;padding:4px 12px;font-weight:700;font-size:13px}
.ok{background:#dcfce7;color:#15803d}.warn{background:#fef3c7;color:#b45309}.bad{background:#fee2e2;color:#b91c1c}
table.t{width:100%;border-collapse:collapse;font-size:13px}table.t th{text-align:left;color:var(--muted);font-weight:600;border-bottom:1px solid var(--line);padding:6px 8px}
table.t td{border-bottom:1px solid var(--line);padding:6px 8px;vertical-align:top}
.small{font-size:12px;color:var(--muted)}a{color:var(--accent)}
.strike{text-decoration:line-through;color:var(--muted)}
footer{margin-top:40px;border-top:1px solid var(--line);padding-top:12px;font-size:12px;color:var(--muted)}
@media print{body{background:#fff}.wrap{padding:0}.card,.tile{break-inside:avoid}a{color:inherit}}
@media (max-width:600px){h1{font-size:24px}.wrap{padding:20px 16px}}`;

const pageShell = (title, body) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title><style>${PAGE_CSS}</style></head><body><div class="wrap">${body}</div></body></html>`;

// Horizontal bar chart as inline SVG (report pages). rows: [{label, value, color}]
function svgBars(rows, { max, width = 560, unit = '', signed = false } = {}) {
  const h = 26, pad = 150, w = width - pad - 50;
  const m = max || Math.max(1, ...rows.map((r) => Math.abs(r.value)));
  const zero = signed ? pad + w / 2 : pad;
  const scale = signed ? w / 2 / m : w / m;
  const bars = rows.map((r, i) => {
    const len = Math.abs(r.value) * scale, x = r.value < 0 ? zero - len : zero, y = i * h + 4;
    return `<text x="${pad - 8}" y="${y + 13}" text-anchor="end" font-size="12" fill="${C.body}">${esc(r.label)}</text>
<rect x="${x}" y="${y}" width="${Math.max(len, 1)}" height="16" rx="3" fill="${r.color || C.accent}"/>
<text x="${r.value < 0 ? x - 4 : x + len + 4}" y="${y + 13}" text-anchor="${r.value < 0 ? 'end' : 'start'}" font-size="12" fill="${C.muted}">${signed && r.value > 0 ? '+' : ''}${r.value}${unit}</text>`;
  }).join('');
  const axis = signed ? `<line x1="${zero}" y1="0" x2="${zero}" y2="${rows.length * h}" stroke="${C.line}"/>` : '';
  return `<svg viewBox="0 0 ${width} ${rows.length * h + 6}" width="100%" role="img" xmlns="http://www.w3.org/2000/svg">${axis}${bars}</svg>`;
}
// ─── end render kit ─────────────────────────────────────────────────────────

// AI Brief Writer — Agent 3 ("Analyst"), second half: turn judged records into briefs.
// One brief for Weave, one per competitor with enough coverage, one for the market.
//
// Numbers are never left to the model: every count and average is computed here
// and handed to the AI as STATS. The AI writes the words, and every claim it makes
// must cite record ids from the evidence it was given — the Fact-Checker checks that next.
const t0 = Date.now();
const cfg = $('Run config').first().json;
const all = $('AI Analyst').all().map((i) => i.json).filter((j) => j._type === 'record');
const relevant = all.filter((r) => r.relevance >= 1 && r.route !== 'discard');

const COMPETITORS = ['Podium', 'Birdeye', 'NexHealth', 'Solutionreach', 'RevenueWell', 'Lighthouse 360'];
const LVL = { none: 0, low: 1, medium: 2, high: 3 };
const avg = (xs) => (xs.length ? xs.reduce((a, b) => a + b, 0) / xs.length : 0);
const countBy = (xs, f) => xs.reduce((m, x) => { const k = f(x); if (k) m[k] = (m[k] || 0) + 1; return m; }, {});
const top = (obj, n) => Object.entries(obj).sort((a, b) => b[1] - a[1]).slice(0, n);

function statsFor(recs) {
  const dates = recs.map((r) => r.published_date).sort();
  return {
    records: recs.length,
    sources: new Set(recs.map((r) => r.source_name)).size,
    date_range: dates.length ? `${dates[0]} to ${dates[dates.length - 1]}` : 'n/a',
    avg_sentiment: +avg(recs.map((r) => r.sentiment)).toFixed(2),
    positive: recs.filter((r) => r.sentiment > 0).length,
    neutral: recs.filter((r) => r.sentiment === 0).length,
    negative: recs.filter((r) => r.sentiment < 0).length,
    themes: Object.fromEntries(top(countBy(recs, (r) => r.theme), 6)),
    evidence: countBy(recs, (r) => r.evidence),
    risks_high_or_medium: recs.filter((r) => LVL[r.risk_to_weave] >= 2).length,
    opportunities_high_or_medium: recs.filter((r) => LVL[r.opportunity_for_weave] >= 2).length,
    archetypes: Object.fromEntries(top(countBy(recs, (r) => r.archetype), 3)),
    ai_judged_share: recs.length ? +(recs.filter((r) => String(r.analysis_source).startsWith('ai:') || r.analysis_source === 'cache').length / recs.length).toFixed(2) : 0,
  };
}

// Evidence pack: the records most worth reading, ranked deterministically.
const score = (r) => r.relevance * 2 + Math.abs(r.sentiment) + LVL[r.risk_to_weave] * 1.5 + LVL[r.opportunity_for_weave] * 1.2
  + (Date.parse(r.published_date) > Date.now() - 21 * 864e5 ? 1 : 0) + Math.min(2, (+r.engagement_points || 0) / 200);
const pack = (recs, n) => [...recs].sort((a, b) => score(b) - score(a)).slice(0, n).map((r) => ({
  id: r.record_id, date: r.published_date, source: r.source_name, title: r.title, key_fact: r.key_fact,
  entity: r.entity, sentiment: r.sentiment, theme: r.theme, evidence: r.evidence, risk: r.risk_to_weave, opportunity: r.opportunity_for_weave,
  archetype: r.archetype, why: r.why,
}));

const subjects = [];
const weave = relevant.filter((r) => r.entity === 'Weave');
subjects.push({ key: 'weave', entity: 'Weave', title: 'Weave brand brief', recs: weave,
  focus: "Weave's reputation, brand perception, risks and what the brand team should do next. Compare with competitors where the evidence allows." });
for (const c of COMPETITORS) {
  const recs = relevant.filter((r) => r.entity === c && r.relevance >= 2);
  if (recs.length >= 3) subjects.push({ key: c.toLowerCase().replace(/\s+/g, '-'), entity: c, title: `Competitor watch: ${c}`, recs,
    focus: `What ${c} is doing, how it is perceived, and what it means for Weave (threats and openings).` });
}
const market = relevant.filter((r) => r.entity === 'Market' && r.relevance >= 2);
if (market.length >= 3) subjects.push({ key: 'market', entity: 'Market', title: 'Market landscape: AI at the front desk', recs: market,
  focus: 'Trends in AI agents and customer communication that change the market Weave competes in, and what Weave should watch.' });
// Weave's brief also sees the strongest competitor items so it can compare.
const rivalsForWeave = pack(relevant.filter((r) => COMPETITORS.includes(r.entity) && r.relevance >= 2), 8);

const WRITER_SYSTEM = `You write weekly brand-intelligence briefs for the brand and data team at Weave Communications.
Write for a busy marketing lead: plain English, specific, no hype, no filler.

HARD RULES
1. Use ONLY facts found in EVIDENCE. Never add outside knowledge, names, numbers or dates.
2. Every claim must cite at least one evidence id in "cite" (e.g. ["GL-1a2b3c4d"]). Only cite ids that appear in EVIDENCE.
3. Numbers (counts, averages, shares) may come ONLY from STATS — copy them exactly.
4. If the evidence is thin, say so plainly instead of stretching it.

Return JSON:
{"headline": "<=14 words, the single most important takeaway",
 "summary": "2-3 sentences for someone who reads nothing else",
 "sections": [{"title": "What happened", "claims": [{"text": "...", "cite": ["GL-..."]}]},
              {"title": "How the brand is perceived", "claims": [...]},
              {"title": "Risks to watch", "claims": [...]},
              {"title": "Openings for Weave", "claims": [...]}],
 "archetype_read": {"text": "1-2 sentences: which brand archetype the coverage casts this company as, and whether that helps Weave", "cite": ["GL-..."]},
 "actions": [{"action": "a concrete next step for the Weave team", "why": "one sentence", "cite": ["GL-..."]}]}
Use 2-4 claims per section (fewer if evidence is thin) and exactly 3 actions.`;

function validateBrief(ids) {
  const known = new Set(ids);
  return (b) => {
    if (!b || typeof b.headline !== 'string' || typeof b.summary !== 'string') return 'missing headline or summary';
    if (!Array.isArray(b.sections) || b.sections.length < 2) return 'need at least 2 sections';
    const claims = [...b.sections.flatMap((s) => (Array.isArray(s.claims) ? s.claims : [])), ...(Array.isArray(b.actions) ? b.actions : [])];
    if (claims.length < 4) return 'too few claims';
    for (const c of claims) {
      if (!Array.isArray(c.cite) || !c.cite.length) return `every claim needs a "cite" array — missing on: "${String(c.text || c.action).slice(0, 60)}"`;
    }
    const cited = claims.flatMap((c) => c.cite);
    if (cited.length && cited.filter((id) => known.has(id)).length / cited.length < 0.5) return 'most cited ids are not in EVIDENCE — cite only the given ids';
    if (!Array.isArray(b.actions) || !b.actions.length) return 'missing actions';
    return null;
  };
}

// Used only when every AI provider is down: a plain brief built from the top records.
function rulesBrief(s, evidence, st) {
  const neg = evidence.filter((e) => e.sentiment < 0 || e.risk !== 'none').slice(0, 3);
  const pos = evidence.filter((e) => e.sentiment > 0).slice(0, 3);
  const claim = (e) => ({ text: `${e.title} (${e.source}, ${e.date}).`, cite: [e.id] });
  return {
    headline: `${s.entity}: ${st.records} items tracked, average sentiment ${fmtSent(st.avg_sentiment)}`,
    summary: `AI writing was unavailable for this run, so this brief lists the highest-priority source items without interpretation. ${st.records} items from ${st.sources} sources were tracked between ${st.date_range}.`,
    sections: [
      { title: 'Highest-priority items', claims: evidence.slice(0, 4).map(claim) },
      { title: 'Negative or risky coverage', claims: neg.map(claim) },
      { title: 'Positive coverage', claims: pos.map(claim) },
    ].filter((x) => x.claims.length),
    archetype_read: null,
    actions: [{ action: 'Review the items above manually; the AI analysis will resume on the next run.', why: 'AI provider unavailable during this run.', cite: evidence.slice(0, 1).map((e) => e.id) }],
  };
}

const jobs = subjects.map((s) => async () => {
  const st = statsFor(s.recs);
  const evidence = pack(s.recs, 25);
  const extra = s.entity === 'Weave' ? rivalsForWeave : [];
  const allEvidence = [...evidence, ...extra.filter((e) => !evidence.some((x) => x.id === e.id))];
  const base = { key: s.key, entity: s.entity, title: s.title, stats: st, evidence: allEvidence, run_id: cfg.run_id, run_date: cfg.run_date };
  if (!evidence.length) return { ...base, brief: rulesBrief(s, evidence, st), written_by: 'rules_fallback', write_error: 'no evidence' };
  try {
    const res = await AI.complete({
      name: `brief:${s.key}`, system: WRITER_SYSTEM, effort: 'medium', maxTokens: 3500, timeoutMs: 150000, temperature: 0.3,
      user: `BRIEF: ${s.title}\nFOCUS: ${s.focus}\nPERIOD: ${st.date_range}\n\nSTATS:\n${JSON.stringify(st, null, 1)}\n\nEVIDENCE:\n${JSON.stringify(allEvidence)}`,
      validate: validateBrief(allEvidence.map((e) => e.id)),
    });
    return { ...base, brief: res.data, written_by: `${res.provider}:${res.model}`, write_ms: res.ms };
  } catch (e) {
    return { ...base, brief: rulesBrief(s, evidence, st), written_by: 'rules_fallback', write_error: `${e.kind || 'error'}: ${String(e.message).slice(0, 160)}` };
  }
});

const briefs = await AI.pool(jobs, 3);
return [
  ...briefs.map((b) => ({ json: { _type: 'brief', ...b } })),
  { json: { _type: 'ai_run', step: 'writer', briefs: briefs.length, ai: AI.summary(), duration_ms: Date.now() - t0 } },
];

// ─── Groundline AI client ───────────────────────────────────────────────────
// Shared by every AI node. scripts/build_workflow.py pastes this file at the top
// of each AI Code node, so the retry / fallback / cost rules live in one place.
//
// Provider chain: Muse Spark (Meta Model API) → Gemini (backup) → caller's rule fallback.
// Both providers speak the OpenAI Chat Completions format, so one client covers both.
//
// What it handles:
//   429 / 5xx / timeout / network  → retry with exponential backoff + jitter (honours Retry-After)
//   400 "unsupported parameter"    → retry once without the optional params
//   401 / 403 / 404                → don't retry; move to the next provider
//   reply is not valid JSON, or fails the caller's schema check → one "repair" round-trip
//   every provider failed          → throws AIError; the caller falls back to rules
// Every call is metered: tokens, cost, latency, retries, provider used.
const __http = this.helpers.httpRequest.bind(this.helpers);

const AI = (() => {
  const env = (k, d = '') => { try { const v = $env[k]; return v === undefined || v === null || v === '' ? d : String(v); } catch (e) { return d; } };
  const real = (k) => k && !/^your_|_here$|^changeme$/i.test(k);

  // USD per 1M tokens. Muse: Meta Model API list price. Gemini: free tier = $0.
  const PROVIDERS = [
    { id: 'muse', label: 'Muse Spark', base: env('MUSE_BASE_URL', 'https://api.meta.ai/v1'), key: env('MUSE_API_KEY'),
      model: env('MUSE_MODEL', 'muse-spark-1.3'), price: { in: +env('MUSE_PRICE_IN', '1.25'), out: +env('MUSE_PRICE_OUT', '4.25') } },
    { id: 'gemini', label: 'Gemini', base: env('GEMINI_BASE_URL', 'https://generativelanguage.googleapis.com/v1beta/openai'), key: env('GEMINI_API_KEY'),
      model: env('GEMINI_MODEL', 'gemini-2.5-flash'), price: { in: +env('GEMINI_PRICE_IN', '0'), out: +env('GEMINI_PRICE_OUT', '0') } },
  ].filter((p) => real(p.key));

  const MAX_TRIES = +env('AI_MAX_TRIES', '4');
  const BASE_DELAY_MS = +env('AI_BASE_DELAY_MS', '1500');
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  const metrics = { calls: 0, ok: 0, failed: 0, retries: 0, repairs: 0, provider_fallbacks: 0,
    tokens_in: 0, tokens_out: 0, cost_usd: 0, latency_ms: [], by_provider: {}, errors: [] };

  class AIError extends Error { constructor(msg, kind) { super(msg); this.kind = kind; } }

  function parseJson(text) {
    if (typeof text !== 'string') throw new AIError('empty reply', 'malformed');
    let t = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
    try { return JSON.parse(t); } catch (e) { /* fall through */ }
    const a = t.indexOf('{'), b = t.lastIndexOf('}');
    if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { /* fall through */ } }
    throw new AIError('reply is not valid JSON: ' + t.slice(0, 120), 'malformed');
  }

  const statusOf = (e) => e.status || e.httpCode || e.statusCode || (e.response && e.response.status) || 0;
  const retryAfterMs = (e) => {
    const h = (e.response && e.response.headers) || {};
    const v = h['retry-after'] || h['Retry-After'];
    return v && Number.isFinite(+v) ? Math.min(+v * 1000, 30000) : 0;
  };

  async function post(p, body, timeoutMs) {
    const t0 = Date.now();
    const res = await __http({
      method: 'POST', url: p.base.replace(/\/$/, '') + '/chat/completions',
      headers: { Authorization: `Bearer ${p.key}`, 'Content-Type': 'application/json' },
      body, json: true, timeout: timeoutMs,
    });
    return { res, ms: Date.now() - t0 };
  }

  // One provider, with retries. Returns parsed + validated JSON or throws.
  async function callProvider(p, task) {
    const messages = [{ role: 'system', content: task.system }, { role: 'user', content: task.user }];
    let optional = { response_format: { type: 'json_object' }, reasoning_effort: task.effort || 'low' };
    let repaired = false;
    for (let attempt = 1; attempt <= MAX_TRIES; attempt++) {
      metrics.calls++;
      try {
        const body = { model: p.model, messages, max_completion_tokens: task.maxTokens || 4000, temperature: task.temperature ?? 0.2, ...optional };
        const { res, ms } = await post(p, body, task.timeoutMs || 90000);
        const u = res.usage || {};
        const tin = u.prompt_tokens || 0, tout = u.completion_tokens || 0;
        const cost = (tin * p.price.in + tout * p.price.out) / 1e6;
        metrics.tokens_in += tin; metrics.tokens_out += tout; metrics.cost_usd += cost; metrics.latency_ms.push(ms);
        const bp = (metrics.by_provider[p.id] = metrics.by_provider[p.id] || { calls: 0, tokens_in: 0, tokens_out: 0, cost_usd: 0 });
        bp.calls++; bp.tokens_in += tin; bp.tokens_out += tout; bp.cost_usd += cost;

        const text = res.choices && res.choices[0] && res.choices[0].message && res.choices[0].message.content;
        let data, problem;
        try { data = parseJson(text); problem = task.validate ? task.validate(data) : null; }
        catch (e) { problem = e.message; }
        if (!problem) { metrics.ok++; return { data, provider: p.id, model: p.model, ms, tokens_in: tin, tokens_out: tout, cost_usd: cost, attempts: attempt }; }

        // Malformed or off-schema reply: show the model its own mistake once.
        if (repaired) throw new AIError(`invalid reply after repair: ${problem}`, 'malformed');
        repaired = true; metrics.repairs++;
        messages.push({ role: 'assistant', content: String(text || '').slice(0, 6000) });
        messages.push({ role: 'user', content: `Your reply was rejected: ${problem}. Reply again with ONLY the corrected JSON object, nothing else.` });
        continue;
      } catch (e) {
        if (e instanceof AIError) throw e;
        const st = statusOf(e);
        const msg = String(e.message || e).slice(0, 200);
        if (st === 400 && optional.response_format && /response_format|reasoning|unsupported|unknown/i.test(JSON.stringify((e.response && e.response.data) || msg))) {
          optional = {}; metrics.retries++; continue;          // provider rejects an optional param → drop it
        }
        if ([401, 403, 404].includes(st)) throw new AIError(`${p.label} ${st}: ${msg}`, 'auth');
        const retryable = !st || st === 408 || st === 409 || st === 429 || st >= 500;
        if (!retryable || attempt === MAX_TRIES) throw new AIError(`${p.label} ${st || 'network'}: ${msg}`, st === 429 ? 'rate_limit' : 'unavailable');
        metrics.retries++;
        const backoff = BASE_DELAY_MS * 2 ** (attempt - 1) + Math.floor(Math.random() * 400);
        await sleep(Math.max(backoff, retryAfterMs(e)));
      }
    }
    throw new AIError(`${p.label}: retries exhausted`, 'unavailable');
  }

  // Public: try each provider in order. task = { name, system, user, validate, effort, maxTokens, timeoutMs }
  async function complete(task) {
    if (!PROVIDERS.length) {
      metrics.failed++;
      metrics.errors.push({ task: task.name, error: 'no AI provider configured (set MUSE_API_KEY or GEMINI_API_KEY in .env)' });
      throw new AIError('no AI provider configured', 'no_provider');
    }
    // task.prefer lets a caller pick a different model first — the fact-checker uses this
    // so that, when both keys exist, a second model checks the first one's work.
    const order = task.prefer ? [...PROVIDERS].sort((a, b) => (b.id === task.prefer) - (a.id === task.prefer)) : PROVIDERS;
    let last;
    for (let i = 0; i < order.length; i++) {
      try { return await callProvider(order[i], task); }
      catch (e) {
        last = e;
        metrics.errors.push({ task: task.name, provider: order[i].id, kind: e.kind || 'error', error: String(e.message).slice(0, 240) });
        if (i < order.length - 1) metrics.provider_fallbacks++;
      }
    }
    metrics.failed++;
    throw last;
  }

  // Run async jobs with a concurrency cap (keeps us under provider rate limits).
  async function pool(jobs, limit) {
    const out = new Array(jobs.length); let next = 0;
    const worker = async () => { while (next < jobs.length) { const i = next++; out[i] = await jobs[i](); } };
    await Promise.all(Array.from({ length: Math.min(limit, jobs.length) }, worker));
    return out;
  }

  function summary() {
    const l = [...metrics.latency_ms].sort((a, b) => a - b);
    const pct = (q) => (l.length ? l[Math.min(l.length - 1, Math.floor(q * l.length))] : 0);
    return { ...metrics, latency_ms: undefined, cost_usd: +metrics.cost_usd.toFixed(6),
      latency_p50_ms: pct(0.5), latency_p95_ms: pct(0.95), latency_max_ms: l[l.length - 1] || 0,
      providers_configured: PROVIDERS.map((p) => `${p.id}:${p.model}`) };
  }

  return { complete, pool, summary, AIError, env, providers: PROVIDERS.map((p) => ({ id: p.id, label: p.label, model: p.model })) };
})();
// ─── end AI client ──────────────────────────────────────────────────────────

// AI Fact-Checker — Agent 4 from the A2 design ("Scorekeeper").
// A second, independent AI pass reads each claim next to the exact source records it
// cites and rules: supported / partial / unsupported. When a Gemini key is set, the
// checker runs on Gemini so a different model checks Muse Spark's writing.
//
// Two layers:
//   1. Deterministic: a claim citing an id that isn't in the evidence is a fabricated
//      citation → unsupported, no AI needed.
//   2. AI: does the cited evidence actually say this?
// Unsupported claims are removed from the published brief and listed in its
// fact-check log. Groundedness = (supported + ½·partial) / claims checked.
const t0 = Date.now();
const briefs = $input.all().map((i) => i.json).filter((j) => j._type === 'brief');
const VERDICTS = ['supported', 'partial', 'unsupported'];

const CHECKER_SYSTEM = `You are a strict, independent fact-checker. You did NOT write these claims.
For each claim you get the claim text and the source records it cites (title + key fact + source + date).
Rule on what the cited records say — not on what is true in the world:
- "supported": the cited records clearly state or directly imply the claim
- "partial": some of the claim is supported, but part is overstated, generalized, or adds detail not in the records
- "unsupported": the cited records do not back the claim
Recommendations ("Weave should...") are "supported" when the situation they respond to is supported.
Return JSON: {"checks":[{"n": <claim number>, "verdict": "supported|partial|unsupported", "reason": "<=20 words"}]}`;

function claimsOf(b) {
  const out = [];
  (b.sections || []).forEach((s, si) => (s.claims || []).forEach((c, ci) => out.push({ where: `s${si}.${ci}`, section: s.title, text: c.text, cite: c.cite || [] })));
  if (b.archetype_read && b.archetype_read.text) out.push({ where: 'archetype', section: 'Archetype read', text: b.archetype_read.text, cite: b.archetype_read.cite || [] });
  (b.actions || []).forEach((a, ai) => out.push({ where: `a${ai}`, section: 'Actions', text: `${a.action} — ${a.why || ''}`, cite: a.cite || [] }));
  return out;
}

const jobs = briefs.map((b) => async () => {
  const ev = Object.fromEntries(b.evidence.map((e) => [e.id, e]));
  const claims = claimsOf(b.brief);
  for (const c of claims) {
    const known = c.cite.filter((id) => ev[id]);
    c.fabricated_cites = c.cite.filter((id) => !ev[id]);
    if (!known.length) { c.verdict = 'unsupported'; c.reason = 'cites no record from the evidence (fabricated or missing citation)'; c.checked_by = 'rule'; }
  }
  const toCheck = claims.filter((c) => !c.verdict);
  let checker = 'none', check_error = null;
  if (toCheck.length && b.written_by !== 'rules_fallback') {
    const payload = toCheck.map((c, n) => ({ n, claim: c.text,
      cited: c.cite.filter((id) => ev[id]).map((id) => ({ id, title: ev[id].title, key_fact: ev[id].key_fact, source: ev[id].source, date: ev[id].date })) }));
    try {
      const res = await AI.complete({ name: `check:${b.key}`, system: CHECKER_SYSTEM, user: JSON.stringify({ claims: payload }),
        prefer: 'gemini', effort: 'low', maxTokens: 300 + 60 * toCheck.length, timeoutMs: 120000, temperature: 0,
        validate: (d) => (!d || !Array.isArray(d.checks) ? 'missing "checks" array'
          : d.checks.filter((x) => x && VERDICTS.includes(x.verdict)).length < Math.ceil(toCheck.length * 0.8) ? 'a verdict is needed for every claim' : null) });
      checker = `${res.provider}:${res.model}`;
      for (const x of res.data.checks) {
        const c = toCheck[x.n];
        if (c && VERDICTS.includes(x.verdict)) { c.verdict = x.verdict; c.reason = String(x.reason || '').slice(0, 200); c.checked_by = checker; }
      }
    } catch (e) { check_error = `${e.kind || 'error'}: ${String(e.message).slice(0, 160)}`; }
  }
  // Rules-written briefs quote their sources verbatim, so they are supported by construction.
  for (const c of claims) if (!c.verdict) {
    if (b.written_by === 'rules_fallback') { c.verdict = 'supported'; c.reason = 'verbatim source title'; c.checked_by = 'rule'; }
    else { c.verdict = 'unverified'; c.reason = 'fact-checker unavailable'; c.checked_by = 'none'; }
  }
  const checked = claims.filter((c) => c.verdict !== 'unverified');
  const sup = checked.filter((c) => c.verdict === 'supported').length, part = checked.filter((c) => c.verdict === 'partial').length;
  const groundedness = b.written_by === 'rules_fallback' ? null : checked.length ? +((sup + 0.5 * part) / checked.length).toFixed(3) : null;
  // A rules-only brief just lists source titles: nothing to fact-check, and we say so rather than claim 100%.
  const status = b.written_by === 'rules_fallback' ? 'ai_offline'
    : groundedness === null ? 'unverified' : groundedness >= 0.85 ? 'verified' : groundedness >= 0.6 ? 'needs_review' : 'failed';

  // Publish only what survived: drop unsupported claims (kept in the log).
  const keep = new Set(claims.filter((c) => c.verdict !== 'unsupported').map((c) => c.where));
  const verdictOf = Object.fromEntries(claims.map((c) => [c.where, c.verdict]));
  const published = { ...b.brief,
    sections: (b.brief.sections || []).map((s, si) => ({ ...s, claims: (s.claims || []).map((c, ci) => ({ ...c, verdict: verdictOf[`s${si}.${ci}`] }))
      .filter((c, ci) => keep.has(`s${si}.${ci}`)) })).filter((s) => s.claims.length),
    archetype_read: b.brief.archetype_read && keep.has('archetype') ? { ...b.brief.archetype_read, verdict: verdictOf.archetype } : null,
    actions: (b.brief.actions || []).map((a, ai) => ({ ...a, verdict: verdictOf[`a${ai}`] })).filter((a, ai) => keep.has(`a${ai}`)),
  };
  return { ...b, published, fact_check: { checker, check_error, status, groundedness, claims_total: claims.length,
    supported: sup, partial: part, unsupported: claims.filter((c) => c.verdict === 'unsupported').length,
    unverified: claims.length - checked.length, fabricated_citations: claims.reduce((n, c) => n + c.fabricated_cites.length, 0), log: claims } };
});

const out = await AI.pool(jobs, 3);
return [
  ...out.map((b) => ({ json: { _type: 'brief', ...b } })),
  { json: { _type: 'ai_run', step: 'fact_checker', ai: AI.summary(), duration_ms: Date.now() - t0 } },
];

